import numpy as np, scipy.special as sps
def gelu(z): return 0.5*z*(1+sps.erf(z/np.sqrt(2)))
grp=np.load('tok_grp.npy'); tk=np.load('tok_kind.npy')
fold=grp%4
def run(l, m, lams, wcls=20.0, sel='data'):
    a=np.load(f'true_a_L{l}.npy').astype(np.float64)
    pre=f'roberta.encoder.layer.{l}.'
    W1=base(pre+'intermediate.dense.weight').astype(np.float64); b1=base(pre+'intermediate.dense.bias').astype(np.float64)
    U=base(pre+'output.dense.weight').astype(np.float64); b2=base(pre+'output.dense.bias').astype(np.float64)
    G=gelu(a@W1.T+b1); F=G@U.T+b2
    res={lam:{0:[],1:[],2:[]} for lam in lams}; den={0:[],1:[],2:[]}
    for f in range(4):
        tr=fold!=f; te=~tr
        w=np.where(tk[tr]==0,wcls,1.0)
        Gt=G[tr]; mu=(w[:,None]*Gt).sum(0)/w.sum()
        if sel=='data':
            sc=(U**2).sum(0)*((w[:,None]*(Gt-mu)**2).sum(0)/w.sum())
        keep=np.sort(np.argsort(-sc)[:m]); pr=np.setdiff1d(np.arange(3072),keep)
        Gc=(Gt[:,keep]-mu[keep])*np.sqrt(w)[:,None]
        R=((Gt[:,pr]-mu[pr])@U[:,pr].T)*np.sqrt(w)[:,None]
        A=Gc.T@Gc; B=Gc.T@R
        for lam in lams:
            if lam is None: D=np.zeros((768,m))
            else: D=np.linalg.solve(A+lam*np.eye(m),B).T
            Un=U[:,keep]+D; b2n=b2+U[:,pr]@mu[pr]-D@mu[keep]
            Fe=G[te][:,keep]@Un.T+b2n
            e=((Fe-F[te])**2).sum(1)
            for k in range(3): res[lam][k].append(e[tk[te]==k])
        Fm=F[tr][tk[tr]==2].mean(0)
        for k in range(3): den[k].append(((F[te]-Fm)**2).sum(1)[tk[te]==k])
    out=[]
    for lam in lams:
        out.append(f'lam={lam}: '+' '.join(f'k{k} {np.concatenate(res[lam][k]).sum()/np.concatenate(den[k]).sum():.4f}' for k in range(3)))
    return out
