def fit(Xs,Ts,ws,m,lam,keep=None):
    X=np.vstack(Xs);T=np.vstack(Ts);w=np.concatenate(ws)
    sw=np.sqrt(w)[:,None]; mu=(w[:,None]*X).sum(0)/w.sum(); tm=(w[:,None]*T).sum(0)/w.sum()
    Xc=(X-mu)*sw
    if keep is None:
        sc=(U**2).sum(0)*(Xc**2).sum(0); keep=np.sort(np.argsort(-sc)[:m])
    Xk=Xc[:,keep]; R=(T-tm)*sw-Xk@U[:,keep].T
    Dd=np.linalg.solve(Xk.T@Xk+lam*np.eye(len(keep)),Xk.T@R).T
    Un=U[:,keep]+Dd; b2n=tm-Un@mu[keep]
    return keep,Un,b2n
